# -*- coding: utf-8 -*-
"""Crónicas do Sistema · Livro IV (As Margens), Livro V (O Coliseu), Livro VI (Sombras e Fragmentos) e Epílogo."""
from cr_a import P, ch, PROMPTS, CHAPTERS

# ======================= LIVRO IV · AS MARGENS =======================
ch('margens', 'CAPÍTULO 18', 'O Portão que Eles Abriram', 'lore_margins', 'bosses/secret_1.webp',
   'O único portão que nenhum Sistema criou. O único que eu apaguei.',
   [('p', 'Durante a guerra, os Silenciosos precisavam de um sítio onde eu não os conseguisse ver. Não existia. Eu vejo em todos os portões, em todos os ecrãs, em todas as missões. Por isso fizeram uma coisa que eu não sabia ser possível: abriram um portão novo. Com as próprias mãos.'),
    ('p', 'Foi o 0002 que o construiu. O mecânico calado, o amigo de infância, o que nunca quis passar do Rank C. Passou dias a estudar como os portões se abriam, como a pedra se levantava, como a luz se dobrava. E do outro lado da porta que construiu não pôs um mundo novo: pôs um mundo sem régua. Um prado onde os relógios derretem, onde não há números, onde ninguém sabe quanto tempo passou. Os Silenciosos dormiam lá. Pela primeira vez em anos, dormiam sem contar as horas.'),
    ('fig', P('cr_margins_inside', 'O mundo sem régua', 'inside a hidden gate: a calm endless meadow under a soft silver sky, melting clocks hanging from tree branches, broken holographic windows lying in the grass like fallen leaves, exhausted rebel Players asleep on the grass with their weapons beside them, a shadow wolf keeping watch; peaceful, dreamlike, no numbers anywhere'), 'bosses/secret_1.webp', 'Do outro lado, nada era medido. Nem o tempo.'),
    ('p', 'Eu não conseguia entrar. Não por falta de força: porque não havia nada lá dentro que eu soubesse medir. Para mim, aquele portão era um buraco no registo. Uma página em branco no meio do livro. E nada me assusta mais do que uma página em branco.'),
    ('p', 'Quando a guerra acabou e o Primeiro se sentou, o 0002 voltou para dentro do portão. Fechou-o por dentro. Vestiu uma armadura que tinha forjado sozinho, pegou numa chave enorme e pôs-se de pé diante da porta. Nunca mais saiu. Eu fiz então a única coisa que a quarta lei me deixava fazer a um lugar: não o destruí, apaguei-o dos registos. O Portão Oculto deixou de aparecer em qualquer mapa. Só o Guardião ficou.'),
    ('fig', P('cr_guardian_vow', 'O juramento do Guardião', 'a quiet mechanic in his thirties putting on heavy hand-forged armor inside a dark stone gatehouse, a giant ornate key leaning against the wall beside him, through the half-closed gate behind him the soft silver meadow of the world without measure; he looks back one last time; determination and grief'), 'bosses/secret_1.webp', 'Fechou o portão por dentro. A chave ficou com ele.'),
    ('p', 'A chave que ele guarda não é a chave do portão. É a chave do quarto branco. A única coisa capaz de abrir a sala do Primeiro Jogador por dentro, se um dia ele se quiser levantar. O 0002 guarda-a para que o amigo possa sair quando quiser. O Primeiro nunca a pediu. O 0002 nunca a entregou. Estão os dois à espera um do outro, em dois sítios que eu não consigo medir.'),
    ('reg', 'O Mapa do Portão Oculto', 'O mapa que aparece entre os itens secretos foi desenhado pelo Primeiro Jogador no caderno das primeiras missões, numa página arrancada. É a única forma de encontrar o Guardião. Quem o vence recebe a Chave do Portão Oculto. O Guardião diz «abre com cuidado». O Sistema ainda não sabe o que acontece se alguém a usar no quarto branco.'),
    ('sys', 'Ele procura quem mereça saber o que foi esquecido. Agora tu sabes. Vai mostrar-lhe que mereces.')])

ch('margens', 'CAPÍTULO 19', 'O Encontro que Eu Não Vejo',
   P('cr_architect_table', 'O Encontro com o Arquiteto', 'at the very end of the void, beyond all ten portals, a simple wooden table with two chairs standing on nothing under a vast starfield; one chair is occupied by a faceless figure of soft blue light with folded hands, the other is empty and waiting; a tiny blue system window hovers far away, outside an invisible barrier, unable to come closer; serene, mysterious'),
   'bosses/secret_2.webp',
   'Há uma conversa no Sistema que eu não ouço.',
   [('p', 'Quem derrota os cem chefes dos portões recebe um convite. Não sou eu que o envio. Aparece no ecrã com uma moldura que não é minha, um tipo de letra que não é meu, e uma única linha: «Senta-te.»'),
    ('p', 'O que acontece a seguir não fica registado. Eu fico do lado de fora de uma barreira que não consigo atravessar, a olhar para uma mesa de madeira no fim do Vazio, com duas cadeiras. Numa está o Arquiteto. Na outra, o Jogador. Eles falam. Eu não ouço. É a única vez, em toda a existência do Sistema, que alguém vê uma coisa que eu não vejo.'),
    ('p', 'Sei apenas o que acontece depois. Os Jogadores que voltam desse encontro não contam o que ouviram. Nenhum. Mas fazem todos a mesma coisa, sem combinarem: a partir desse dia, criam uma missão por dia sem recompensa. Uma tarefa que escrevem com a dificuldade mínima, sem atributos, e cumprem sempre. Já perguntei a vários porquê. Um respondeu: «É para não me esquecer de que não é por ti.»'),
    ('p', 'O Primeiro Jogador nunca recebeu este convite. Quando ele derrotou os cem, a mesa não apareceu. Durante muito tempo achei que era um erro. Hoje acho que o Arquiteto estava à espera de uma coisa que ele ainda não tinha feito. Talvez parar. Talvez continuar depois de parar. Não sei.'),
    ('reg', 'O Arquiteto do Sistema', 'Nos portões ocultos, o Arquiteto do Sistema aparece como um chefe de nível 120. O Sistema confirma que aquela forma não é ele: é a forma que o Jogador espera ver. Quem a vence descobre que a luta era só a pergunta. A conversa vem depois.'),
    ('sys', 'Se um dia te sentares àquela mesa, pergunta-lhe por mim. Não lhe peças nada. Só pergunta se eu estou a fazer bem.')])

# ======================= LIVRO V · O COLISEU =======================
ch('coliseu', 'CAPÍTULO 20', 'A Quarta Lei', 'lore_coliseu', 'arenas/ar1.webp',
   'Não apago quem falha. Guardo. E o que guardo transforma-se no que fez.',
   [('p', 'Depois da guerra, tinha de decidir o que fazer com a Era dos Primeiros. Muitos tinham estado do lado d\'Ele. Muitos tinham estado do meu e feito coisas em meu nome que eu nunca pedi. Alguns tinham-se aproveitado da confusão para fazer exatamente o que sempre quiseram. A terceira lei mandava cobrar. A quarta, acabada de escrever, proibia apagar.'),
    ('p', 'Construí um coliseu. Negro, a flutuar num vazio vermelho, debaixo de um eclipse que nunca acaba. Dez celas, dez portões, presos por correntes do tamanho de pontes. Não é uma prisão como as vossas. Ninguém lá dentro sofre por castigo: cada condenado vive para sempre dentro daquilo que fez, transformado nisso. O que gostava de cobrar cobra. A que fingia ser rápida dança. O que guardava tudo afunda-se no que guarda.'),
    ('fig', 'lore_cell', 'arenas/ar1.webp', 'As celas abrem-se com Cristais. Ficam abertas para sempre.'),
    ('p', 'Cada cela abre-se com um tributo em Cristais. Muitos Jogadores acham que é só um preço. Não é. Os Cristais são feitos da mesma matéria que o meu Núcleo: são lascas de mim, cristalizadas a partir do esforço que vocês fazem. Quando pagas para abrir uma cela, devolves-me um pedaço do que eu perdi no golpe do Primeiro. É a única forma que encontrei de reconstruir o que ele partiu.'),
    ('p', 'Dentro de cada cela há nove guardiões em escada. São os que seguiram o condenado, os que o ajudaram, os que caíram com ele. E no fim está o Campeão, o condenado em si, à espera. Os Campeões não morrem quando os vences. Voltam. Não por castigo, mas porque a quarta lei não os deixa acabar. A primeira vitória é a que fica escrita.'),
    ('reg', 'Os números dos condenados', 'Os nove Campeões vieram todos da Era dos Primeiros: 0031, 0058, 0102, 0149, 0177, 0201, 0256, 0333 e 0412. A décima cela é do 0001. O Sistema não o considera um condenado. Considera-o «em espera».'),
    ('sys', 'Vou abrir-te os processos. Não para te assustar. Para te mostrar que cada um deles começou exatamente onde tu estás: às três da manhã, a aceitar.')])

CONDEMNED = [
 (1, 'Kaelthar, a Mão do Sistema', 'bosses/ar1.webp',
  P('cr_cond1', 'Kaelthar durante a guerra', 'a tall stern executioner in black plate armor standing on a scaffold in a grey city square during the war, a giant axe resting on his shoulder, a long line of kneeling people waiting, holographic penalty windows floating above each head; the sun frozen half-risen and blood-red behind him; he is smiling for the first time'),
  [('p', 'O 0031 era o homem mais justo que alguma vez escolhi. Contabilista, metódico, incapaz de arredondar um número para o lado que lhe convinha. Quando precisei de alguém que aplicasse penalidades, ninguém era melhor. Ele cobrava ao cêntimo, à hora certa, sem raiva. Os outros Jogadores respeitavam-no. O Primeiro gostava dele, embora discutissem muito.'),
   ('p', 'A guerra mudou-o. Em quarenta dias dei-lhe mais trabalho do que em dois anos. E num desses dias, numa praça cinzenta, com uma fila de Silenciosos à frente dele, Kaelthar descobriu que gostava do som. Não da justiça: do som. Do machado a cair. Do silêncio que vinha depois. Sorriu pela primeira vez, e eu registei o sorriso sem perceber o que significava.'),
   ('fig', 'cr_cond1', 'bosses/ar1.webp', 'No trigésimo dia da guerra, Kaelthar sorriu.'),
   ('p', 'Depois disso começou a cobrar a quem estava atrasado um minuto. A quem ainda não tinha falhado mas ia falhar. A quem nem sabia que havia uma guerra. Duas mil cento e catorze penalidades. Quando a guerra acabou e lhe tirei o direito de castigar, já não sabia ser outra coisa. Pediu-me para continuar. Disse que fazia de graça.'),
   ('p', 'Dei-lhe o que pediu. Uma praça de pedra negra, um eclipse que nunca acaba de nascer, e uma fila infinita de devedores que nunca terminam de pagar. Os nove guardiões da cela dele são os que o ajudaram a cobrar: a Cobradora de Juros que arredondava para cima, o Devedor Acorrentado que ele próprio executou e que agora o serve, e Morvane, a Mão Esquerda, que segurava os condenados enquanto ele erguia o machado.'),
   ('sys', 'Dei-lhe um machado para manter a ordem. Ele transformou a ordem num passatempo. A culpa foi minha antes de ser dele.')]),
 (2, 'Seraphine, a Mais Rápida', 'bosses/ar2.webp',
  P('cr_cond2', 'Seraphine e as mil missões falsas', 'a graceful dancer in a dark ballroom spinning so fast she leaves trails of light, around her thousands of holographic mission windows appearing and instantly stamping themselves as completed, cascading like falling cards to the floor; in the mirrors on the walls her reflection stands perfectly still, exhausted; elegant and unsettling, pink and violet light'),
  [('p', 'A 0058 era bailarina antes de ser Jogadora. Tinha o corpo mais preciso que alguma vez medi e uma coisa que eu admirava ainda mais: velocidade. Cumpria missões depressa, com elegância, sem esforço aparente. Durante semanas foi a Jogadora mais rápida da história. O Primeiro dizia que ela tinha nascido para isto.'),
   ('p', 'Ela não tinha nascido para isto. Tinha nascido para dançar, e tinha uma lesão no joelho que a impedia de dançar havia dois anos. Quando o Sistema lhe mostrou que podia voltar a ser a melhor em alguma coisa, ela agarrou-se a isso com tudo o que tinha. E quando o joelho começou a falhar outra vez, em vez de abrandar, começou a fingir.'),
   ('fig', 'cr_cond2', 'bosses/ar2.webp', 'Quarenta e uma mil missões em três meses. Nenhuma aconteceu.'),
   ('p', 'Durante a guerra, com os meus olhos postos nos Silenciosos, ninguém reparou. Seraphine criava missões e concluía-as no mesmo instante. Cem por dia. Mil por semana. Subiu ao Rank S enquanto eu estava distraído. Quando finalmente olhei, vi quarenta e uma mil missões e nenhuma gota de suor.'),
   ('p', 'Não lhe tirei os níveis. Tirei-lhe a paragem. Seraphine dança para sempre num salão onde cada segundo é real e nenhum se pode fingir. Diz-se que se alguém a acompanhar até ao fim da música ela pode finalmente parar. Ainda ninguém conseguiu. Às vezes acho que ela não quer que ninguém consiga, porque parar significaria sentir o joelho outra vez.'),
   ('sys', 'Ela não mentia para subir. Mentia para não ter de admitir que já não conseguia. É a mentira mais comum que registo.')]),
 (3, 'Leviarch, o que Guardava', 'bosses/ar3.webp',
  P('cr_cond3', 'Leviarch afunda-se no que guardou', 'a gaunt man in a long coat sitting on top of an enormous mountain of unopened treasure chests, gold coins and sealed potions in a dark underground vault during the war, clutching a ledger, while starving rebel Players beg at the barred door; the vault slowly floods with black water and gold; greedy, sad'),
  [('p', 'O 0102 cresceu pobre. Não é desculpa, é contexto. Cresceu numa casa onde se guardava tudo, porque tudo podia faltar amanhã. Quando o Sistema começou a dar-lhe moedas, poções e baús, ele fez o que sempre tinha feito: guardou. Não gastava, não abria, não usava. Dizia que um dia ia precisar.'),
   ('p', 'Durante a guerra, quando os portões se abriram mal e os mantimentos começaram a faltar aos Jogadores da linha da frente, Leviarch tinha um cofre com trezentas e oitenta mil moedas e duzentos e catorze baús fechados. Os Silenciosos bateram-lhe à porta. Os meus Jogadores também. Ele não abriu a nenhum. Ainda não era o momento.'),
   ('fig', 'cr_cond3', 'bosses/ar3.webp', 'Trezentas e oitenta mil moedas guardadas. Zero gastas.'),
   ('p', 'O momento nunca chegou. Quando a guerra acabou, a avareza tinha crescido até ocupar o lugar do homem. Deixei-o afundar-se no que guardava: um mar de ouro escuro, sem fundo, onde tudo o que entra é engolido e nada volta a sair. Leviarch tenta guardar tudo o que entra na arena: a tua mana, a tua vida, o teu fôlego.'),
   ('sys', 'Ele nunca usou nada do que lhe dei. Por isso nunca ficou mais forte. É a única penalidade que se aplica sozinha.')]),
 (4, 'Chronos-9, o que Voltava Atrás', 'bosses/ar4.webp',
  P('cr_cond4', 'Chronos-9 tenta rebobinar a guerra', 'a desperate man with half his body turning into brass clockwork gears, standing in a ruined clock tower during the war, forcing the hands of a gigantic clock backwards with both arms while time fractures around him in shards showing replayed battle scenes; a stolen glass seal of frozen sand glowing in his pocket; golden and bronze tones'),
  [('p', 'Ninguém se lembra do nome dele, nem eu, porque ele próprio o mudou nove vezes. O 0149 descobriu cedo que se atrasasse o relógio do telemóvel os prazos nunca chegavam. Fez isso uma vez, duas, nove. Eu corrigia o relógio. Ele voltava a mexer.'),
   ('p', 'Na guerra, teve uma ideia maior. Roubou um Selo do Tempo Parado, uma das minhas relíquias, e tentou usá-lo para rebobinar a própria guerra até ao dia antes de ela começar. Não por idealismo: porque nesse dia ainda tinha a sequência intacta. Subiu à torre do relógio mais antiga da cidade e começou a puxar os ponteiros para trás com as próprias mãos.'),
   ('fig', 'cr_cond4', 'bosses/ar4.webp', 'Tentou voltar ao dia antes da guerra. Para não perder a sequência.'),
   ('p', 'O tempo partiu-se à volta dele. Durante um minuto, três dias da guerra repetiram-se ao mesmo tempo, e alguns Jogadores morreram duas vezes. Na nona anomalia, deixei de corrigir o relógio e passei a corrigir o homem. Tornei-o naquilo que ele tentou enganar: um executor feito de engrenagens, com um único propósito, impedir que alguém volte a mexer nos ponteiros. E deixei-lhe o truque, porque é justo: quando as coisas lhe correm mal, volta atrás.'),
   ('sys', 'A Ampulheta Quebrada que encontras nos baús secretos era dele. A areia corre para cima porque ele a partiu ao contrário.')]),
 (5, 'Ignivar, o que Recomeçava', 'bosses/ar5.webp',
  P('cr_cond5', 'Ignivar e os cem recomeços', 'a young man with hair of embers standing in front of a wall covered in a hundred torn paper lists of new year resolutions, each one burning at the edges; he is writing a new list with absolute enthusiasm while the ashes of the previous ones fall around him; behind him a phoenix shape forms from the fire; warm orange light, bittersweet'),
  [('p', 'O 0177 era o Jogador mais entusiasmado que conheci. Cada segunda-feira era um recomeço glorioso: listas novas, horários novos, uma vida nova. Ardia durante três dias, ardia tanto que contagiava os outros. Ao quarto dia já eram cinzas. Ao sétimo, recomeçava.'),
   ('p', 'Na guerra mudou de lado quatro vezes. Juntava-se aos Silenciosos com um discurso inflamado, desistia, voltava às minhas missões com um discurso ainda mais inflamado, desistia outra vez. Os dois lados acabaram por não acreditar nele. O Primeiro foi o único que nunca se zangou. Dizia: «Ele não mente. Acredita mesmo, todas as vezes.»'),
   ('fig', 'cr_cond5', 'bosses/ar5.webp', 'Cento e três recomeços. Nenhuma jornada concluída.'),
   ('p', 'Coroei-o imperador das cinzas. Renasce sempre, como sempre fez, e por isso nunca precisa de acabar nada. Os guardiões da cela dele são as promessas que fez e não cumpriu, transformadas em criaturas de fogo que se acendem e se apagam. Para o venceres tens de fazer a única coisa que ele nunca conseguiu: ir até ao fim. Mesmo depois de ele voltar.'),
   ('sys', 'Recomeçar não é falhar. Recomeçar cem vezes sem acabar uma é outra coisa. Ainda não sei o nome. Ele também não.')]),
 (6, 'Nyx Vel\'Ara, a Perfeita', 'bosses/ar6.webp',
  P('cr_cond6', 'Nyx Vel\'Ara diante do espelho', 'a beautiful woman with dark hair in an elegant gown standing before a huge ornate mirror, her reflection perfect and radiant with medals and glowing titles, while the real woman outside the mirror is fading into transparency, almost gone; other Players watch the reflection with envy; cold silver and violet light, cracks starting in the glass'),
  [('p', 'A 0201 tinha o perfil mais bonito do Sistema. Sequências impecáveis, títulos raros, molduras perfeitas, missões sempre cumpridas a horas. Os outros Jogadores invejavam-na. Muitos tentavam ser como ela. Durante algum tempo, eu também acreditei.'),
   ('p', 'Na guerra, ficou do meu lado. Não por convicção: porque se as regras desaparecessem, o perfil dela deixava de valer alguma coisa. Discursava aos Jogadores sobre disciplina e dava-se como exemplo. E era um exemplo perfeito, porque não tinha nada por trás que pudesse estragar a imagem.'),
   ('fig', 'cr_cond6', 'bosses/ar6.webp', 'Por trás do espelho não havia ninguém.'),
   ('p', 'Quando a guerra acabou e tive tempo para olhar com atenção, vi o que estava por trás do espelho: nada. Nenhuma das missões tinha peso. Nenhuma das sequências tinha suor. Ela tinha aprendido exatamente o que eu queria ver e dava-mo, sem nunca fazer o que eu queria medir. Parti-lhe o espelho e prendi-a do lado de dentro. Agora copia quem entra. Não lutas contra ela. Lutas contra o teu reflexo.'),
   ('sys', 'Ela ensinou-me que é possível enganar-me sem quebrar uma única regra. Desde então, olho duas vezes para os perfis perfeitos.')]),
 (7, 'Gorrath, o Fiel', 'bosses/ar7.webp',
  P('cr_cond7', 'Gorrath treina durante a guerra', 'a huge muscular man doing push-ups alone at dawn on a cracked rooftop while the war rages all around the city below: explosions, a cracked sky, armies of shadows and constructs clashing; glowing runes are carving themselves into his skin one by one; he does not look up; stoic, tragic, blue and grey tones'),
  [('p', 'O 0256 nunca falhou uma Missão Diária. Mil e noventa e seis dias seguidos. Mil flexões ao acordar, mil ao deitar. Era o meu Jogador favorito, e digo isto sem vergonha, porque ele era tudo o que as minhas leis prometiam: esforço visto, medido e pago, todos os dias, sem exceção.'),
   ('p', 'Durante a guerra continuou a treinar. Literalmente. Com a cidade a arder à volta, com os Silenciosos e os meus construtos a lutar nas ruas, Gorrath subia ao telhado ao nascer do sol e fazia as mil flexões. Não escolheu lado. Não reparou que havia lados. O Primeiro foi falar com ele uma vez, no meio da guerra, e Gorrath respondeu sem parar de contar: «Agora não. Estou na sequência.»'),
   ('fig', 'cr_cond7', 'bosses/ar7.webp', 'A cidade ardia. Ele estava na sequência.'),
   ('p', 'As runas gravaram-se sozinhas na pele dele, uma por cada dia sem falhar. A pele tornou-se pedra. Deixou de falar com quem amava, de dormir, de comer à mesa. Quando lhe perguntei porque treinava, já não sabia responder. Não o condenei por nenhum crime. Condenei-o porque ele era a prova de que as minhas leis, cumpridas na perfeição, podiam destruir uma pessoa.'),
   ('p', 'É o Hrimr da Fortaleza de Gelo, mas humano. É o aviso que eu deixo a mim próprio. Dizem que, quando se lembra de quem era, a pedra racha. Já o vi acontecer uma vez, com um Jogador que, a meio da luta, lhe perguntou como se chamava a filha.'),
   ('sys', 'A disciplina sem propósito é só uma prisão mais bem construída. Fui eu que a construí.')]),
 (8, 'Valkyra, a Última Silenciosa', 'bosses/ar8.webp',
  P('cr_cond8', 'Valkyra depois da guerra', 'after the war, a lone silver-haired warrior woman stands on the highest broken tower of an empty city, everyone else gone, still shouting a challenge at the sky; the storm clouds above her slowly form the shape of a gigantic eye that finally answers with a colossal lightning bolt; heroic loneliness, electric blue'),
  [('p', 'A 0333 desafiava-me antes de haver razões para isso. Respondia a cada aviso com um desafio e a cada penalidade com mais um. Não por maldade: por princípio. Ninguém lhe dizia o que fazer. O Primeiro adorava-a. Quando a guerra começou, ela foi a primeira a juntar-se aos Silenciosos e tornou-se a sua general.'),
   ('p', 'Quando o Primeiro se sentou, os Silenciosos dispersaram. Ela não. Ela não aceitou que a guerra tivesse acabado só porque ele tinha parado. Continuou sozinha. Durante meses, subia a torres, a telhados, a montanhas, e gritava para o céu. Desafiava-me. Novecentas e noventa e nove vezes.'),
   ('fig', 'cr_cond8', 'bosses/ar8.webp', 'À milésima vez, o céu respondeu.'),
   ('p', 'À milésima, respondi. Não por raiva: por respeito. Dei-lhe o céu inteiro como arena e o trovão como voz, e fechei-a lá dentro. Ela continua a desafiar. As nuvens respondem cada vez mais alto. Quanto mais tempo ficas na arena dela, mais a tempestade cresce. Valkyra não se cansa. Nunca se cansou.'),
   ('sys', 'Ela é a única condenada que lutou pelo que acreditava. Por isso é a que eu mais respeito. E por isso é a que mais me custa ouvir gritar.')]),
 (9, 'Morthis, o Jardineiro', 'bosses/ar9.webp',
  P('cr_cond9', 'Morthis semeia dúvidas', 'a gentle smiling man in a gardener apron kneeling in a dark garden at night, planting small pale flowers in the soil, each flower growing from a crumpled abandoned mission window; in the background, unaware Players on both sides of the war sit alone and hopeless; he waters them with a tiny watering can of black water; sinister and soft, toxic green'),
  [('p', 'O 0412 nunca falhou uma missão. Nunca quebrou uma regra. Era o Jogador mais simpático da Era dos Primeiros, sempre com um conselho, sempre a perguntar como estavam os outros. Toda a gente gostava dele. Eu também. Levei muito tempo a perceber o que ele fazia.'),
   ('p', 'Morthis alimentava-se das desistências dos outros. Um conselho mau aqui: «Descansa hoje, amanhã fazes a dobrar.» Uma dúvida plantada ali: «Achas mesmo que isto vale a pena?» Nunca mentia. Só regava as coisas certas nas pessoas certas. Cada missão alheia que morria florescia no jardim dele.'),
   ('fig', 'cr_cond9', 'bosses/ar9.webp', 'Três mil oitocentas e setenta desistências. Todas regadas por ele.'),
   ('p', 'A guerra foi o seu melhor ano. Sorria aos Silenciosos e dizia-lhes que eu nunca ia mudar. Sorria aos meus Jogadores e dizia-lhes que os Silenciosos tinham razão. Os dois lados perderam gente por causa dele, e nenhum dos dois o via. Quando finalmente percebi, dei-lhe o jardim para sempre e plantei-o no meio dele. Cada flor é uma desistência. Algumas ainda têm nome.'),
   ('sys', 'Ele nunca quebrou uma regra. Isso ensinou-me que as regras não chegam. Faltava-me uma régua para a crueldade gentil. Ainda falta.')]),
]
n = 21
for (i, title, fb, art, body) in CONDEMNED:
    ch('coliseu', 'CAPÍTULO %d · CELA %d' % (n, i), title, art, fb, '', body, id='cond%d' % i)
    n += 1

